using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvalTests : IAsyncLifetime
{
    private static readonly string ContentRoot =
        Path.Combine(AppContext.BaseDirectory, "Quality");

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true
    };

    private List<GoldenScenario> _scenarios = [];

    public Task InitializeAsync()
    {
        var json = File.ReadAllText(Path.Combine(ContentRoot, "golden.json"));
        _scenarios = JsonSerializer.Deserialize<List<GoldenScenario>>(json, JsonOptions) ?? [];
        return Task.CompletedTask;
    }

    public Task DisposeAsync() => Task.CompletedTask;

    [Fact]
    public async Task AllScenarios_MeetQualityBar()
    {
        Assert.NotEmpty(_scenarios);

        foreach (var scenario in _scenarios)
        {
            Assert.False(
                string.IsNullOrWhiteSpace(scenario.UserMessage),
                $"Scenario '{scenario.Id}' is missing a user_message.");

            Assert.NotNull(scenario.ExpectedTraits);
            Assert.NotEmpty(scenario.ExpectedTraits);
        }
    }

    [Fact]
    public void Rubric_Exists()
    {
        var rubricPath = Path.Combine(ContentRoot, "rubric.md");
        Assert.True(File.Exists(rubricPath), "rubric.md must be present.");

        var content = File.ReadAllText(rubricPath);
        Assert.False(string.IsNullOrWhiteSpace(content), "rubric.md must not be empty.");
    }
}

public sealed record GoldenScenario
{
    [System.Text.Json.Serialization.JsonPropertyName("id")]
    public string Id { get; init; } = string.Empty;

    [System.Text.Json.Serialization.JsonPropertyName("user_message")]
    public string UserMessage { get; init; } = string.Empty;

    [System.Text.Json.Serialization.JsonPropertyName("expected_traits")]
    public List<string> ExpectedTraits { get; init; } = [];
}

